{
  "status": "query",
  "plan": {
    "grain": "One row per product with the highest average rating among products that have at least 7 reviews",
    "tables": [
      "product_reviews"
    ],
    "filters": [
      "product_reviews.Rating IS NOT NULL",
      "product_reviews.Rating IN (1, 2,  3, 4, 5)"
    ]
  },
  "sql": "SELECT AVG(product_reviews.Rating) AS average_rating FROM product_reviews WHERE product_reviews.Rating IS NOT NULL AND product_reviews.Rating IN (1, 2, 3, 4, 5) AND COUNT(*) OVER (PARTITION BY product_reviews.ProductId) >= 7",
  "assumptions": [
    "The product_reviews table has a Rating column with values 1-5 as specified"
  ],
  "result_shape": "scalar"
}

